async function apiStream(path,opts={},onToken=()=>{}){const {timeoutMs:requestTimeout=52000,idempotencyKey,signal:externalSignal,...fetchOptions}=opts,ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),requestTimeout),headers={'Content-Type':'application/json',...((nativeSessionToken||webSessionToken)?{Authorization:`Bearer ${nativeSessionToken||webSessionToken}`}:{ }),...(fetchOptions.headers||{})};if(idempotencyKey)headers['Idempotency-Key']=idempotencyKey;const signal=externalSignal?(typeof AbortSignal.any==='function'?AbortSignal.any([ctrl.signal,externalSignal]):externalSignal):ctrl.signal;try{const response=await fetch(`${API}${path}`,{credentials:'include',...fetchOptions,headers,signal});if(!response.ok){const json=(response.headers.get('content-type')||'').includes('application/json'),body=json?await response.json().catch(()=>({})):{};throw Object.assign(new Error(friendlyHttp(response.status,body,json,path)),{status:response.status,code:body.code||`HTTP_${response.status}`,details:body.details||'',attemptedCandidates:body.attemptedCandidates||0})}if(!response.body)throw new Error('Streaming is unavailable in this browser or WebView.');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',doneData=null;const processFrame=frame=>{let event='message',data=[];for(const line of frame.split(/\r?\n/)){if(line.startsWith('event:'))event=line.slice(6).trim();else if(line.startsWith('data:'))data.push(line.slice(5).trim())}if(!data.length)return;let value;try{value=JSON.parse(data.join('\n'))}catch{return}if(event==='reset')onToken('\u0000POTHUB_RESET\u0000');if(event==='token'&&typeof value.text==='string')onToken(value.text);if(event==='done')doneData=value;if(event==='error')throw Object.assign(new Error(value.message||'The agent stream stopped. Retry the request.'),{code:value.code||'AGENT_STREAM_FAILED',details:value.details||'',attemptedCandidates:value.attemptedCandidates||0});};while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let split;while((split=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,split);buffer=buffer.slice(split+2);processFrame(frame)}}if(buffer.trim())processFrame(buffer);if(!doneData)throw new Error('The agent stream ended before completion. Retry to resume the conversation.');return doneData}catch(e){if(e.status)throw e;throw Object.assign(new Error(friendlyNetwork(e,path,requestTimeout)),{code:e.name==='AbortError'?'TIMEOUT':'NETWORK'})}finally{clearTimeout(timer)}}

function friendlyHttp(status,d,isJson,path){const ref=d?.requestId?` Reference: ${String(d.requestId).slice(0,80)}.`:'';if(native()&&!API)return `${APK_NO_API} Check the app configuration and retry.`;if(status===401)return `Your session is missing or expired. Sign in again.${ref}`;if(status===402)return `You do not have enough credits for this action. Add credits and retry.${ref}`;if(status===403)return `This action is not available for the current account or connection. Check linked accounts and permissions.${ref}`;if(status===404||status===405)return `This feature is unavailable in the current service version. Update PotHub or retry after deployment.${ref}`;if(status===413)return `This item is too large for this operation. Attach it through the large-file upload flow or split it into smaller parts.${ref}`;if(status===422)return `${d?.error||d?.message||'PotHub rejected the request format.'}${ref}`;if(status===429)return `PotHub is busy. Wait a moment, then retry.${ref}`;if(status>=500)return `PotHub encountered a server problem. Retry once; if it continues, share the diagnostic reference with support.${ref}`;return `PotHub could not complete that action. Check the configuration and retry.${ref}`;}
function friendlyNetwork(e,path,timeoutMs){if(e?.name==='AbortError')return `PotHub took too long to respond. Check your connection and retry.${native()&&!API?` ${APK_NO_API}`:''}`;if(native()&&!API)return `${APK_NO_API} Check the app configuration and retry.`;return 'Could not reach PotHub. Check your internet connection and retry.';}
async function api(path,opts={}){const {timeoutMs:requestTimeout=25000,noRetry=false,idempotencyKey,signal:externalSignal,...fetchOptions}=opts,method=String(fetchOptions.method||'GET').toUpperCase(),retryable=!noRetry&&(['GET','HEAD'].includes(method)||!!idempotencyKey);let attempt=0,sessionRefreshed=false;while(true){const ctrl=new AbortController(),t=setTimeout(()=>ctrl.abort(),requestTimeout);try{const headers={'Content-Type':'application/json',...((nativeSessionToken||webSessionToken)?{Authorization:`Bearer ${nativeSessionToken||webSessionToken}`}:{}),...(fetchOptions.headers||{})};if(idempotencyKey)headers['Idempotency-Key']=idempotencyKey;const signal=externalSignal?(typeof AbortSignal.any==='function'?AbortSignal.any([ctrl.signal,externalSignal]):externalSignal):ctrl.signal;const r=await fetch(`${API}${path}`,{credentials:'include',...fetchOptions,headers,signal});const isJson=(r.headers.get('content-type')||'').includes('application/json');const d=isJson?await r.json().catch(()=>({})):{};if(r.status===401&&!sessionRefreshed&&firebaseSessionActive&&firebaseAuth?.currentUser&&path!=='/api/auth/firebase-exchange'){sessionRefreshed=true;webSessionToken='';try{await exchangeFirebaseSession(firebaseAuth.currentUser);continue}catch{}}if(!r.ok)throw Object.assign(new Error(friendlyHttp(r.status,d,isJson,path)),{status:r.status,code:d.code||`HTTP_${r.status}`,requestId:d.requestId||r.headers.get('x-request-id')||null});return d;}catch(e){if(retryable&&attempt<1&&(!e.status||e.status>=500)){await new Promise(r=>setTimeout(r,180));attempt++;continue}if(e.status)throw e;throw Object.assign(new Error(friendlyNetwork(e,path,requestTimeout)),{code:e.name==='AbortError'?'TIMEOUT':'NETWORK'})}finally{clearTimeout(t)}}}

