async function exchangeFirebaseSession(firebaseUser){const idToken=await firebaseUser.getIdToken();if(firebaseExchangeFlights.has(idToken))return firebaseExchangeFlights.get(idToken);const flight=(async()=>{const exchanged=await api('/api/auth/firebase-exchange',{method:'POST',body:JSON.stringify({idToken}),timeoutMs:15000,noRetry:true});if(!exchanged.session)throw Error('Google sign-in did not return a PotHub session.');webSessionToken=exchanged.session;googleIdToken='';firebaseSessionActive=true;try{sessionStorage.setItem('pothub-session-v1',webSessionToken);sessionStorage.setItem('pothub-auth-provider-v1','google')}catch{}return exchanged})();firebaseExchangeFlights.set(idToken,flight);try{return await flight}finally{if(firebaseExchangeFlights.get(idToken)===flight)firebaseExchangeFlights.delete(idToken)}}



let googleRedirectPromise=null;
let browserTicketPromise=null;
let browserTicketValue='';
// Only consume Firebase's redirect result when this tab explicitly initiated the
// Google redirect fallback. Without this guard, an old Firebase redirect result can
// be replayed during a later Developer/GitHub visit and switch workspaces unexpectedly.
const GOOGLE_REDIRECT_PENDING='pothub-google-redirect-pending-v1';
const GOOGLE_REDIRECT_MARKER='pothub_google_redirect';
function markGoogleRedirectPending(){try{localStorage.setItem(GOOGLE_REDIRECT_PENDING,JSON.stringify({at:Date.now(),expiresAt:Date.now()+10*60*1000}))}catch{}}
function clearGoogleRedirectPending(){try{localStorage.removeItem(GOOGLE_REDIRECT_PENDING)}catch{}}
function isGoogleRedirectPending(){try{const raw=localStorage.getItem(GOOGLE_REDIRECT_PENDING);if(!raw)return false;const value=JSON.parse(raw);if(!value?.expiresAt||Date.now()>value.expiresAt){localStorage.removeItem(GOOGLE_REDIRECT_PENDING);return false}return true}catch{return false}}
function setGoogleRedirectMarker(enabled){try{const url=new URL(location.href);if(enabled)url.searchParams.set(GOOGLE_REDIRECT_MARKER,'1');else url.searchParams.delete(GOOGLE_REDIRECT_MARKER);window.history.replaceState({},'',url.pathname+url.search+url.hash)}catch{}}
function isGoogleRedirectReturn(){try{return new URL(location.href).searchParams.get(GOOGLE_REDIRECT_MARKER)==='1'}catch{return false}}
function clearGoogleRedirectState(){clearGoogleRedirectPending();setGoogleRedirectMarker(false)}
function consumeGoogleRedirect(){const pending=isGoogleRedirectPending(),marker=isGoogleRedirectReturn();if(!pending&&!marker)return Promise.resolve(null);if(!googleRedirectPromise){googleRedirectPromise=(async()=>{await firebaseAuth.authStateReady();const result=await getRedirectResult(firebaseAuth);const user=result?.user||firebaseAuth?.currentUser;clearGoogleRedirectState();if(!user){if(marker)throw Error("Google returned to PotHub without an authenticated account. Add the Firebase auth handler as an authorized redirect URI on the Firebase web OAuth client, and add this site's domain to Firebase Authorized Domains, then retry Creator sign-in.");return null}const me=await exchangeFirebaseSession(user);if(!me.user)throw Error('Google sign-in succeeded, but PotHub could not verify the Creator account.');return {...me,authProvider:'google'}})().catch(e=>{clearGoogleRedirectState();throw e}).finally(()=>{googleRedirectPromise=null})}return googleRedirectPromise}
// React StrictMode may clean up the first startup effect while the one-time ticket exchange is in flight.
// Keep the promise at module scope so a second effect run awaits the same result.
function consumeBrowserTicket(ticket){if(!browserTicketPromise||browserTicketValue!==ticket){browserTicketValue=ticket;browserTicketPromise=api('/api/auth/browser-exchange',{method:'POST',body:JSON.stringify({ticket}),timeoutMs:15000,noRetry:true}).then(exchanged=>{webSessionToken=exchanged.session||'';firebaseSessionActive=false;try{sessionStorage.removeItem('pothub-auth-provider-v1')}catch{}if(!webSessionToken&&!exchanged.cookieSession)throw Error('GitHub sign-in returned no session. Please try Developer sign-in again.');try{if(webSessionToken)sessionStorage.setItem('pothub-session-v1',webSessionToken);else sessionStorage.removeItem('pothub-session-v1')}catch{}return exchanged})}return browserTicketPromise}

