function flattenSelectOptions(children){
  const out=[];
  React.Children.forEach(children,child=>{
    if(!React.isValidElement(child))return;
    if(child.type===React.Fragment)out.push(...flattenSelectOptions(child.props.children));
    else if(child.type==='option')out.push(child);
  });
  return out;
}
