const fn=TASK_FUNCTION[task]||'';const eligible=(Array.isArray(rows)?rows:[]).filter(row=>String(row.function||'').toLowerCase()===String(fn).toLowerCase());
const primary=await prepareAgentCandidates(eligible,task,fn);
