async function generateImage(promptOverride){const imagePrompt=(typeof promptOverride==='string'?promptOverride:prompt).trim();const ags=await functionAgents('Image');if(!ags.length){setMissingAgentFunction('Image');return setError('Add an agent for Image to continue.')}if(imagePrompt.length<8)return showError(new Error('Describe the image in at least 8 characters.'));setChatStage(0);setBusy('image');try{const headers=await agentHeadersForFunction(ags,'image');if(!headers)throw Error('No working Image key could be decrypted. Open Agents to reconfigure one.');setChatStage(1);const operationId=uid();const d=await api('/api/creator/image',{method:'POST',timeoutMs:52000,idempotencyKey:operationId,headers:{...headers.headers,'X-Pothub-Workspace':'creator'},body:JSON.stringify({operationId,prompt:imagePrompt,count:Number(imageCount)||1,aspectRatio:'1:1',agentConfig:headers.agentConfig})});setChatStage(2);const imageRows=[];for(const im of (d.images||[])){const blob=im.url?await fetch(im.url).then(r=>{if(!r.ok)throw Error('Generated image download link expired. Retry the same image operation.');return r.blob()}):new Blob([Uint8Array.from(atob(im.contentBase64),c=>c.charCodeAt(0))],{type:im.mimeType||'image/png'}),id=uid();await db.attachments.put({id,name:im.filename||`pothub-image-${id}.png`,type:blob.type,size:blob.size,kind:'image',blob,createdAt:new Date().toISOString()});imageRows.push({id,name:im.filename||`pothub-image-${id}.png`,mimeType:blob.type,size:blob.size,blob})}const userMsg={id:uid(),role:'user',text:imagePrompt,createdAt:new Date().toISOString()},assistantMsg={id:uid(),role:'assistant',text:'Image generated.',images:imageRows,createdAt:new Date().toISOString()};const next=[...messages,userMsg,assistantMsg];setMessages(next);let cid=chatId;if(!cid){cid=uid();setChatId(cid);await db.chats.put({id:cid,title:imagePrompt.slice(0,48)||'Image creation',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})}await db.messages.bulkPut(next.map(m=>({...m,chatId:cid})));if(Number.isFinite(d.creditsRemaining))setCredits(d.creditsRemaining);setChatList(await db.chats.orderBy('updatedAt').reverse().toArray());setPrompt('');queueCloudSync()}catch(e){if(typeof promptOverride==='string')setPrompt(promptOverride);showError(e)}finally{setBusy('')}}
async function imagePromptVideoChain(direction){const userDirection=typeof direction==='string'?direction:'';const source=attach.find(f=>f.type?.startsWith('image/'));if(!source)return showError(new Error('Attach an image first, then choose Image → prompt → video.'));const chats=await functionAgents('Chat');if(!chats.length){setMissingAgentFunction('Chat');return setError('Configure a Chat agent to analyze the image and write a video prompt.')}const videos=await functionAgents('Video');if(!videos.length)return false;setBusy('chain');try{const headers=await agentHeadersForFunction(chats,'chat');if(!headers)throw Error('No working Chat key could be decrypted.');const dataUrl=await imageDataUrl(source,1000000);const operationId1=uid();const first=await api('/api/agent/chat',{method:'POST',timeoutMs:52000,idempotencyKey:operationId1,headers:{...headers.headers,'X-Pothub-Workspace':'creator'},body:JSON.stringify({operationId:operationId1,message:'Analyze the attached image and describe its subject, composition, style, lighting, colors, and visible environment. Be factual; do not invent details.',history:[],attachments:[{id:uid(),name:source.name,type:source.type,size:source.size,dataUrl}],agentConfig:headers.agentConfig})});const visualDescription=String(first.text||first.response||'').trim();if(!visualDescription)throw Error('The image-analysis agent returned no description.');if(Number.isFinite(first.creditsRemaining))setCredits(first.creditsRemaining);const operationId2=uid();const second=await api('/api/agent/chat',{method:'POST',timeoutMs:52000,idempotencyKey:operationId2,headers:{...headers.headers,'X-Pothub-Workspace':'creator'},body:JSON.stringify({operationId:operationId2,message:`Write one production-ready image-to-video prompt based on this image description. Preserve the same subject and visual style; specify subtle natural motion, camera movement, scene continuity, and avoid changing identity or composition.${String(userDirection||'').trim()?` Follow this direction from the user where it is compatible with the image: "${String(userDirection).trim().slice(0,400)}".`:''} Return only the prompt.

Image description:
${visualDescription}`,history:[],attachments:[],agentConfig:headers.agentConfig})});const videoPrompt=String(second.text||second.response||'').trim();if(!videoPrompt)throw Error('The prompt-writing agent returned no video prompt.');if(Number.isFinite(second.creditsRemaining))setCredits(second.creditsRemaining);const now=new Date().toISOString(),userMessage={id:uid(),role:'user',text:`Image → prompt → video
Image: ${source.name}
Image analysis: ${visualDescription}
Video prompt: ${videoPrompt}`,createdAt:now},assistantMessage={id:uid(),role:'assistant',text:`**Video prompt prepared**

${videoPrompt}

Starting video generation…`,createdAt:now};setMessages(m=>[...m,userMessage,assistantMessage]);setPrompt(videoPrompt);setBusy('');await generateVideo(videoPrompt);}catch(e){showError(e)}finally{setBusy('')}}
async function generateVideo(promptOverride){const videoPrompt=(typeof promptOverride==='string'?promptOverride:prompt).trim();const ags=await functionAgents('Video');if(!ags.length)return false;if(!videoPrompt)return showError(new Error('Describe the video first.'));setBusy('video');let row=null;try{const now=new Date().toISOString(),id=uid(),cid=chatId||uid();if(!chatId){setChatId(cid);await db.chats.put({id:cid,title:videoPrompt.slice(0,48)||'Video generation',createdAt:now,updatedAt:now})}row={id,providerJobId:'',operationId:uid(),provider:normalizeProvider(ags[0].provider),prompt:videoPrompt,aspectRatio:videoOptions.aspectRatio,state:'submitting',progress:0,createdAt:now,updatedAt:now,model:ags[0].model};await db.videoJobs.put(row);queueCloudSync();const videoMessage={id:row.id,chatId:cid,role:'assistant',text:'Video submission is being started.',videoJob:row,createdAt:now};await db.messages.put(videoMessage);queueCloudSync();setMessages(m=>[...m,videoMessage]);setChatList(await db.chats.orderBy('updatedAt').reverse().toArray());if(!promptOverride)setPrompt('');let started=false,failures=[];for(const candidate of ags){try{const provider=normalizeProvider(candidate.provider),operationId=provider===row.provider&&candidate.model===row.model?row.operationId:uid();row={...row,provider,model:candidate.model,operationId,state:'submitting',error:'',updatedAt:new Date().toISOString()};await db.videoJobs.put(row);await persistVideoMessage(row);const key=await decryptSecret(candidate.secret),jobId=await geminiVideo.submit(row.prompt,videoOptions,key,candidate.model,provider,operationId);row={...row,providerJobId:jobId,state:'queued',updatedAt:new Date().toISOString()};await db.videoJobs.put(row);await persistVideoMessage(row);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:row}:x));pollVideo(row,candidate);started=true;break}catch(e){if(/timed out|failed to fetch|network error|aborted/i.test(String(e?.message||'')))throw e;failures.push(`${candidate.label}: ${e.message}`);row={...row,state:'submitting',error:e.message||'Provider submission failed.',updatedAt:new Date().toISOString()};await db.videoJobs.put(row);await persistVideoMessage(row)}}if(!started){row={...row,state:'failed',error:`No configured video agent could start a job. ${failures.join(' | ')}`,updatedAt:new Date().toISOString()};await db.videoJobs.put(row);await persistVideoMessage(row);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:row}:x));throw Error(row.error)}}catch(e){showError(e)}finally{setBusy('')}}
async function persistVideoMessage(row){const msg=await db.messages.get(row.id);if(msg){await db.messages.put({...msg,videoJob:row,text:row.state==='ready'?'Video is ready.':row.state==='failed'?'Video generation failed.':'Video generation in progress.'});queueCloudSync()}}
async function pollVideo(row,agent){let wait=3000,elapsed=0;while(elapsed<600000){try{const key=await decryptSecret(agent.secret),s=row.providerJobId?await geminiVideo.status(row.providerJobId,key,row.provider||agent.provider):{state:'submitting',progress:0};row={...row,...s,updatedAt:new Date().toISOString()};await db.videoJobs.put(row);await persistVideoMessage(row);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:row}:x));if(s.state==='ready'){const delivered=await geminiVideo.fetchResult(row.providerJobId,key,row.provider||agent.provider);const blob=delivered.blob||delivered;row={...row,blob,state:'ready',progress:100,updatedAt:new Date().toISOString(),creditsCharged:delivered.creditsCharged||0};if(Number.isFinite(delivered.creditsRemaining))setCredits(delivered.creditsRemaining);await db.videoJobs.put(row);await persistVideoMessage(row);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:row}:x));return}if(s.state==='failed')return}catch(e){row={...row,lastError:e.message,updatedAt:new Date().toISOString()};if(/not enough credits|insufficient credits/i.test(e.message||'')){row.state='failed';row.error='The video is ready, but your balance is too low to retrieve it. Buy credits, then retry the video result.';setCheckoutOpen(true)}await db.videoJobs.put(row);await persistVideoMessage(row);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:row}:x));if(row.state==='failed')return;}await new Promise(r=>setTimeout(r,wait));elapsed+=wait;wait=Math.min(wait*1.7,30000)}row={...row,state:'paused',error:'This job is still saved. Reopen PotHub to resume checking it; no credits are charged until delivery.'};await db.videoJobs.put(row);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:row}:x))}
async function retryVideoResult(row){try{const candidates=await functionAgents('Video'),agent=candidates.find(a=>normalizeProvider(a.provider)===(row.provider||'gemini')&&a.model===row.model);if(!agent)return;const key=await decryptSecret(agent.secret),delivered=await geminiVideo.fetchResult(row.providerJobId,key,row.provider||agent.provider),blob=delivered.blob||delivered,updated={...row,blob,state:'ready',progress:100,error:'',lastError:'',updatedAt:new Date().toISOString(),creditsCharged:delivered.creditsCharged||0};await db.videoJobs.put(updated);await persistVideoMessage(updated);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:updated}:x));if(Number.isFinite(delivered.creditsRemaining))setCredits(delivered.creditsRemaining)}catch(e){showError(e)}}
async function cancelVideo(row){let cancellation={providerCancelled:false};try{const candidates=await functionAgents('Video'),agent=candidates.find(a=>normalizeProvider(a.provider)===(row.provider||'gemini')&&a.model===row.model);if(agent){const key=await decryptSecret(agent.secret);cancellation=await geminiVideo.cancel(row.providerJobId,key,row.provider||agent.provider).catch(()=>({providerCancelled:false}))}}finally{const updated={...row,state:'cancelled',error:cancellation.providerCancelled?'The provider accepted the cancellation request. No credits are charged.':'Polling stopped locally; the provider may continue in the background. No credits are charged unless a result is delivered.',updatedAt:new Date().toISOString()};await db.videoJobs.put(updated);await persistVideoMessage(updated);setMessages(m=>m.map(x=>x.id===row.id?{...x,videoJob:updated}:x))}}
async function saveBackup(includeMedia=false){const {createZip,sanitizeBackupData}=await import('../lib/backup');const tables=['projects','runs','chats','messages','attachments','videoJobs','creditEvents','promptLibrary','backups'],data={schemaVersion:2,createdAt:new Date().toISOString(),includesMedia:!!includeMedia,tables:{}},mediaFiles=[],mediaPaths=new Map();let mediaBytes=0;for(const row of await db.attachments.toArray()){if(includeMedia&&row.blob){const path=`media/attachments/${row.id}-${String(row.name||'file').replace(/[^A-Za-z0-9._-]/g,'_').slice(0,100)}`,bytes=new Uint8Array(await row.blob.arrayBuffer());mediaBytes+=bytes.length;mediaPaths.set(row.id,path);mediaFiles.push({name:path,data:bytes})}}for(const row of await db.videoJobs.toArray()){if(includeMedia&&row.blob){const path=`media/videos/${row.id}.mp4`,bytes=new Uint8Array(await row.blob.arrayBuffer());mediaBytes+=bytes.length;mediaPaths.set(`video:${row.id}`,path);mediaFiles.push({name:path,data:bytes})}}if(mediaBytes>50*1024*1024)throw Error('Media backup exceeds the 50 MB limit. Export fewer large videos first.');for(const t of tables){const rows=await db.table(t).toArray();if(t==='attachments')data.tables[t]=rows.map(({blob,...a})=>({...a,mediaPath:mediaPaths.get(a.id)||null,mediaIncluded:!!mediaPaths.get(a.id)}));else if(t==='videoJobs')data.tables[t]=rows.map(({blob,...j})=>({...j,mediaPath:mediaPaths.get(`video:${j.id}`)||null,mediaIncluded:!!mediaPaths.get(`video:${j.id}`)}));else if(t==='messages')data.tables[t]=rows.map(m=>({...m,images:(m.images||[]).map(({blob,...im})=>({...im,mediaPath:mediaPaths.get(im.id)||null,mediaIncluded:!!mediaPaths.get(im.id)})),videoJob:m.videoJob?(({blob,...j})=>({...j,mediaPath:mediaPaths.get(`video:${j.id}`)||null,mediaIncluded:!!mediaPaths.get(`video:${j.id}`)}))(m.videoJob):undefined}));else data.tables[t]=rows}const safeSettings=(await db.settings.toArray()).filter(x=>!/(agent|secret|token|key|passcode|auth|session|credential)/i.test(String(x.key||''))).map(x=>({key:x.key,value:x.value,updatedAt:x.updatedAt||null}));data.tables.settings=safeSettings;const safeData=sanitizeBackupData(data),json=new TextEncoder().encode(JSON.stringify(safeData));if(includeMedia){const zip=createZip([{name:'backup.json',data:json},...mediaFiles]);await saveBlob(new Blob([zip],{type:'application/zip'}),'pothub-backup.zip')}else await saveBlob(new Blob([json],{type:'application/json'}),'pothub-backup.json');await db.settings.put({key:`backup-reminder:${user?.id||'local'}`,value:Date.now()});setBackupReminderOpen(false)}
async function restoreBackup(file){const {readZip,backupDecoder}=await import('../lib/backup');let d,media=new Map();if(/\.zip$/i.test(file.name)||file.type==='application/zip'){const files=readZip(await file.arrayBuffer()),backup=files.get('backup.json');if(!backup)throw Error('ZIP does not contain backup.json.');d=JSON.parse(backupDecoder.decode(backup));for(const [name,bytes] of files)if(name.startsWith('media/'))media.set(name,bytes)}else d=JSON.parse(await file.text());if(d.schemaVersion!==2||!d.tables||typeof d.tables!=='object')throw Error('Unsupported or invalid backup file.');const allowed=new Set(['projects','runs','chats','messages','attachments','videoJobs','creditEvents','backups','promptLibrary','settings']);for(const [t,rows] of Object.entries(d.tables)){if(!allowed.has(t)||!Array.isArray(rows)||rows.length>50000)throw Error('Backup contains an unsupported table or too many records.')}if(media.size){const blobFor=(path,type)=>{const bytes=media.get(path);if(!bytes)throw Error(`Backup media is missing or damaged: ${path}`);return new Blob([bytes],{type:type||'application/octet-stream'})};for(const row of d.tables.attachments||[]){if(row.mediaPath){row.blob=blobFor(row.mediaPath,row.type);delete row.mediaPath}}for(const row of d.tables.videoJobs||[]){if(row.mediaPath){row.blob=blobFor(row.mediaPath,'video/mp4');delete row.mediaPath}}for(const m of d.tables.messages||[]){for(const im of m.images||[])if(im.mediaPath){im.blob=blobFor(im.mediaPath,im.mimeType||'image/png');delete im.mediaPath}if(m.videoJob?.mediaPath){m.videoJob.blob=blobFor(m.videoJob.mediaPath,'video/mp4');delete m.videoJob.mediaPath}}}const counts=Object.fromEntries(Object.entries(d.tables).map(([k,v])=>[k,Array.isArray(v)?v.length:0]));setRestorePreview({data:d,counts,mediaIncluded:media.size>0});}
function updateCheckout(field,value){setCheckoutForm(v=>({...v,[field]:value}))}
async function beginCheckout(pack){try{setSelectedPack(pack);setPaymentBusy(true);setPaymentStatus('Preparing secure checkout…');const d=await api('/api/billing/config');if(!d.enabled||d.flow!=='flutterwave-v4-card')throw Error('Flutterwave v4 billing is not configured on this deployment.');setCheckoutOpen(true);setPaymentStatus('Enter your billing and card details.')}catch(e){showError(e)}finally{setPaymentBusy(false)}}
async function submitCheckout(e){e.preventDefault();if(!selectedPack)return showError(new Error('Choose a credit pack first.'));setPaymentBusy(true);setPaymentStatus('Preparing secure payment…');let authorizing=false;const clearAttempts=()=>{try{for(const key of Object.keys(sessionStorage))if(key.startsWith('pothub_checkout_attempt_'))sessionStorage.removeItem(key)}catch{}};try{const base={email:checkoutForm.email.trim(),name:checkoutForm.name.trim(),phone:checkoutForm.phone.trim()};const d=await api('/api/billing/checkout',{method:'POST',body:JSON.stringify({...base,packId:selectedPack.id,currency:'USD'}),idempotencyKey:(()=>{const key=`pothub_checkout_attempt_${selectedPack.id}`;let value='';try{value=sessionStorage.getItem(key)||'';if(!value){value=`pothub-checkout-${crypto.randomUUID()}`;sessionStorage.setItem(key,value)}}catch{value=`pothub-checkout-${selectedPack.id}-${uid()}`}return value})(),timeoutMs:30000,noRetry:true});setPaymentRef(d.reference||'');if(d.status==='awaiting_card'){authorizing=true;setPaymentStatus('Sending card details securely to Flutterwave…');const a=await api('/api/billing/authorize',{method:'POST',body:JSON.stringify({reference:d.reference,...base,card:cardForm}),timeoutMs:45000,noRetry:true});setCardForm({number:'',expiryMonth:'',expiryYear:'',cvv:''});if(a.status==='requires_redirect'&&/^https:\/\//i.test(String(a.redirectUrl||''))){setPaymentStatus(a.message||'Redirecting to your bank…');window.location.assign(a.redirectUrl)}else if(a.paid){setCredits(a.credits);setPaymentStatus(a.added?`Payment verified. ${a.added} credits added.`:'Payment verified.');setPaymentRef('');setCheckoutOpen(false);clearAttempts()}else setPaymentStatus(a.message||'Payment submitted. Verify it in a moment.')}else if(d.status==='paid'){const check=await api('/api/billing/verify',{method:'POST',body:JSON.stringify({reference:d.reference}),timeoutMs:20000,noRetry:true});if(check.paid){setCredits(check.credits);setPaymentStatus('This checkout attempt is already paid.');setPaymentRef('');setCheckoutOpen(false);clearAttempts()}else setPaymentStatus(check.message||'Payment is still being reconciled.')}else setPaymentStatus(d.message||'A payment for this attempt is in progress. Verify it shortly.')}catch(e){showError(e);setPaymentStatus(e.message||'Payment failed.');setCardForm({number:'',expiryMonth:'',expiryYear:'',cvv:''});if(authorizing){if(/declined/i.test(String(e.message||'')))clearAttempts();if(!/already submitted|in progress/i.test(String(e.message||'')))setPaymentRef('')}}finally{setPaymentBusy(false)}}
async function verifyPayment(){if(!paymentRef.trim())return showError(new Error('Enter the payment reference.'));setPaymentBusy(true);try{let transactionId='';try{transactionId=sessionStorage.getItem(`pothub_tx_${paymentRef.trim()}`)||''}catch{}const d=await api('/api/billing/verify',{method:'POST',body:JSON.stringify({reference:paymentRef.trim(),transactionId})});if(d.paid){setCredits(d.credits);setPaymentStatus(d.added?`Payment verified. ${d.added} credits added.`:`Payment verified. Balance: ${d.credits} credits.`);try{for(const key of Object.keys(sessionStorage))if(key.startsWith('pothub_checkout_attempt_')||key.startsWith('pothub_tx_'))sessionStorage.removeItem(key)}catch{}setPaymentRef('');setCheckoutOpen(false)}else setPaymentStatus(d.message||'Payment is not confirmed yet.')}catch(e){showError(e)}finally{setPaymentBusy(false)}}
async function saveNewAgent(e){e.preventDefault();try{await reverifyAgentAccess();if(!agentForm.key.trim())throw Error('Enter an API key.');if(agentForm.function==='Video'&&!providersForFunction('Video').some(p=>p.id===normalizeProvider(agentForm.provider)))throw Error('Choose a supported video provider.');if(agentForm.function==='Image'&&!providersForFunction('Image').some(p=>p.id===normalizeProvider(agentForm.provider)))throw Error('Choose a supported image provider.');const saved=await saveAgent(agentForm);setAgents(await db.agents.toArray());await syncSavedData();setAgentForm({...agentForm,key:'',modelVariants:'',id:null,label:'New agent'});setError('');setNotice(`${saved.label} saved securely and queued for account sync.`);if(pendingAiOperation){const op=pendingAiOperation;setPendingAiOperation('');setSection('workspace');if(op==='diagnosis')await diagnose(true);else if(op==='fix')await suggestFix(true)}}catch(e){showError(e)}}
async function testAgent(a){try{await reverifyAgentAccess();if(a.function==='Video'&&!providersForFunction('Video').some(p=>p.id===normalizeProvider(a.provider)))throw Error('This saved video provider is no longer supported.');const key=await decryptSecret(a.secret);const models=[...new Set([a.model,...(Array.isArray(a.models)?a.models:[])].map(model=>normalizeConfiguredModel(a.provider,model)).filter(Boolean))].slice(0,8);const task=a.function.toLowerCase().replace(' generation','').replace('fix','repair');const candidates=models.map(model=>({key,model,provider:normalizeProvider(a.provider)||a.provider,...(a.baseUrl?{baseUrl:a.baseUrl}:{}),task}));const d=await api('/api/agent/test',{method:'POST',body:JSON.stringify({keys:candidates})});const results=Array.isArray(d.results)?d.results:[],testResult=d.best||results.find(result=>result.ok)||results[0]||{},passed=results.some(result=>result.ok);const tested={...a,lastTestOk:passed,lastTestAt:new Date().toISOString(),lastTestLatencyMs:testResult.latencyMs||null,lastTestPreview:String(testResult.preview||'').slice(0,100),lastTestModel:testResult.model||a.model,updatedAt:new Date().toISOString()};await db.agents.put(tested);setAgents(rows=>rows.map(row=>row.id===a.id?tested:row));await syncSavedData();if(!passed)throw Error(results.map(result=>`${result.model}: ${result.error||'test failed'}`).join('; ')||'Agent test failed. Check the provider, model, endpoint and key.');setNotice(`Agent test succeeded using ${testResult.model||a.model} in ${testResult.latencyMs||0} ms. ${testResult.model&&testResult.model!==a.model?'A configured fallback model was used. ':''}${testResult.preview||''}`)}catch(e){try{const failed={...a,lastTestOk:false,lastTestAt:new Date().toISOString()};await db.agents.put(failed);setAgents(rows=>rows.map(row=>row.id===a.id?failed:row));await syncSavedData()}catch{}showError(e)}}

async function savePromptTemplate(){const title=promptTitle.trim()||'Saved prompt';const content=promptDraft.trim();if(!content)return showError(new Error('Enter a prompt to save.'));const row={id:uid(),title,content,category:role==='Creator'?'creator':'developer',starred:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};await db.promptLibrary.put(row);setPromptLibrary(await db.promptLibrary.orderBy('updatedAt').reverse().toArray());await syncSavedData();setPromptTitle('');setPromptDraft('')}
